# 选择框属性

- order: 4

通过 rowSelection.getProps 来控制选择框属性

:::lang=en-us
# Checkbox properties

- order: 4

Controlling checkbox properties with rowSelection.getProps
:::

---

````jsx
import { Table } from '@alifd/next';

const onChange = function(...args) {
        console.log(...args);
    },
    dataSource = () => {
        const result = [];
        for (let i = 0; i < 5; i++) {
            result.push({
                title: {
                    name: `Quotation for 1PCS Nano ${3 + i}.0 controller compatible`
                },
                id: 100306660940 + i,
                time: 2000 + i
            });
        }
        return result;
    },
    render = (value, index, record) => {
        return <a>Remove({record.id})</a>;
    },
    rowSelection = {
        onChange: onChange,
        getProps: (record) => {
            return {
                disabled: record.id === 100306660942
            };
        }
    };

ReactDOM.render(<Table dataSource={dataSource()}
    rowSelection={rowSelection}>
    <Table.Column title="Id" dataIndex="id"/>
    <Table.Column title="Title" dataIndex="title.name"/>
    <Table.Column title="Time" dataIndex="time"/>
    <Table.Column cell={render} width={200}/>
</Table>, mountNode);
````

4.document_content:
# 定制列

- order: 15

定制显示的表格列数

:::lang=en-us
# Customize columns

- order: 15

Customized number of table columns.
:::

---

````jsx
import { Table, Button, Dialog, Checkbox } from '@alifd/next';

const {Group} = Checkbox;
const dataSource = () => {
        const result = [];
        for (let i = 0; i < 5; i++) {
            result.push({
                title: `Quotation for 1PCS Nano ${3 + i}.0 controller compatible`,
                id: 100306660940 + i,
                time: 2000 + i
            });
        }
        return result;
    },
    cols = [{
        title: 'id',
        dataIndex: 'id'
    }, {
        title: 'Title',
        dataIndex: 'title'
    }, {
        title: 'Time',
        dataIndex: 'time'
    }];

class App extends React.Component {
    constructor (props) {
        super(props);
        this.state = {
            dataSource: dataSource(),
            cols: cols
        };
    }
    openDialog = () => {
        Dialog.alert({
            content: this.renderControlContent(),
            title: 'Select columns',
            onOk: () => {
                this.setState({
                    cols: this.changedCols || this.state.cols
                });
                return true;
            }
        });
    }

    renderControlContent() {
        const groupSource = cols.map(col => {
                return {
                    label: col.title,
                    value: col.dataIndex
                };
            }), defaultValue = this.state.cols.map(col => col.dataIndex);
        return <Group dataSource={groupSource} onChange={this.onChange} defaultValue={defaultValue}/>;
    }

    onChange = (value) => {
        this.changedCols = cols.filter(col => value.indexOf(col.dataIndex) > -1);
    }

    renderCols() {
        const {cols} = this.state;
        return cols.map(col => {
            return <Table.Column title={col.title} dataIndex={col.dataIndex} key={col.dataIndex} />;
        });
    }

    render() {
        return (
            <div>
                <p><Button onClick={this.openDialog}> Select columns </Button></p>
                <Table dataSource={this.state.dataSource}>
                    {this.renderCols()}
                </Table>
            </div>
        );
    }
}

ReactDOM.render(<App/>, mountNode);
````

